-- The in-memory working copy of the vault (see db.rs). The files in the vault are the source of truth; this
-- schema only has to hold what they describe, and enforce the rules between them.
--
-- A project holds threads. A thread holds posts (markdown notes), prompts (requests for deliverables),
-- feedback (on a deliverable) and uploads (a manifest for a file kept in the project's attachments). A project
-- also has deliverables (files generated by prompts), user stories, tasks on a board, and its own templates.
-- Templates can also be vault-wide.
--
-- Ids of posts, prompts, feedback, uploads and tasks are unique across the vault, so they are keys on their own;
-- their project and thread columns say where they live.

CREATE TABLE projects (
    slug              TEXT PRIMARY KEY,
    name              TEXT NOT NULL,
    description       TEXT NOT NULL DEFAULT '',
    -- The reading guide: the text of README.md, kept verbatim.
    readme            TEXT NOT NULL DEFAULT '',
    backlog_column_id TEXT NOT NULL DEFAULT '',
    created_at        TEXT NOT NULL,
    updated_at        TEXT NOT NULL
);

CREATE TABLE project_columns (
    project_slug TEXT NOT NULL REFERENCES projects(slug) ON DELETE CASCADE,
    id           TEXT NOT NULL,
    name         TEXT NOT NULL,
    position     INTEGER NOT NULL,
    PRIMARY KEY (project_slug, id)
);

CREATE TABLE threads (
    project_slug TEXT NOT NULL REFERENCES projects(slug) ON DELETE CASCADE,
    slug         TEXT NOT NULL,
    title        TEXT NOT NULL,
    description  TEXT NOT NULL DEFAULT '',
    created_at   TEXT NOT NULL,
    PRIMARY KEY (project_slug, slug)
);

-- Links between threads of a project are bidirectional: each pair is stored once, smaller slug first.
CREATE TABLE thread_links (
    project_slug TEXT NOT NULL,
    a            TEXT NOT NULL,
    b            TEXT NOT NULL,
    PRIMARY KEY (project_slug, a, b),
    CHECK (a < b),
    FOREIGN KEY (project_slug, a) REFERENCES threads(project_slug, slug) ON DELETE CASCADE,
    FOREIGN KEY (project_slug, b) REFERENCES threads(project_slug, slug) ON DELETE CASCADE
);

CREATE TABLE posts (
    id                  TEXT PRIMARY KEY,
    project_slug        TEXT NOT NULL,
    thread_slug         TEXT NOT NULL,
    -- Deliberately not a foreign key: deleting a post leaves its replies in place.
    parent_id           TEXT,
    guiding_question    INTEGER NOT NULL DEFAULT 0,
    version_published   INTEGER NOT NULL DEFAULT 0,
    deliverable_path    TEXT,
    deliverable_version TEXT,
    -- On a "version published" note: the prompt that caused the version. Deliberately not a foreign key, like `parent_id`.
    prompt_id           TEXT,
    created_at          TEXT NOT NULL,
    updated_at          TEXT NOT NULL,
    body                TEXT NOT NULL,
    FOREIGN KEY (project_slug, thread_slug) REFERENCES threads(project_slug, slug) ON DELETE CASCADE
);
CREATE INDEX posts_by_thread ON posts (project_slug, thread_slug, created_at);

-- A request for a deliverable. `template_id` names the template it was started from, if any.
CREATE TABLE prompts (
    id           TEXT PRIMARY KEY,
    project_slug TEXT NOT NULL,
    thread_slug  TEXT NOT NULL,
    title        TEXT NOT NULL DEFAULT '',
    template_id  TEXT,
    created_at   TEXT NOT NULL,
    updated_at   TEXT NOT NULL,
    body         TEXT NOT NULL,
    FOREIGN KEY (project_slug, thread_slug) REFERENCES threads(project_slug, slug) ON DELETE CASCADE
);

-- The deliverables a prompt produced, by path relative to the project's deliverables/ folder.
CREATE TABLE prompt_deliverables (
    prompt_id TEXT NOT NULL REFERENCES prompts(id) ON DELETE CASCADE,
    position  INTEGER NOT NULL,
    path      TEXT NOT NULL,
    PRIMARY KEY (prompt_id, path)
);

-- Feedback lands on a deliverable (a path under deliverables/, possibly a published version).
CREATE TABLE feedback (
    id                  TEXT PRIMARY KEY,
    project_slug        TEXT NOT NULL,
    thread_slug         TEXT NOT NULL,
    deliverable_path    TEXT NOT NULL,
    deliverable_version TEXT,
    status              TEXT NOT NULL DEFAULT 'open',
    created_at          TEXT NOT NULL,
    updated_at          TEXT NOT NULL,
    body                TEXT NOT NULL,
    -- Who gave it: a name, and when they are someone in Portflow, their Portflow id and role there. `given` says how
    -- it was given: 'in person', 'portflow', 'email' or 'other'. Kept whether or not Portflow is switched on.
    from_name           TEXT,
    from_user           INTEGER,
    from_role           TEXT,
    given               TEXT,
    -- Feedback pulled from Portflow: the comment it is, the comment it answers, and the evidence item (its slug in
    -- the project) and version it is on. Such feedback may have no deliverable (deliverable_path '').
    portflow_comment    INTEGER,
    reply_to            TEXT,
    comment_type        TEXT,
    evidence            TEXT,
    evidence_version    INTEGER,
    FOREIGN KEY (project_slug, thread_slug) REFERENCES threads(project_slug, slug) ON DELETE CASCADE
);
CREATE UNIQUE INDEX feedback_by_comment ON feedback (portflow_comment) WHERE portflow_comment IS NOT NULL;

-- What running a prompt with Claude Code did: how it ended, and what it said and did. Kept as runs/<id>.md in the
-- thread, so the history reads without the app. `prompt_id` is deliberately not a foreign key: deleting a prompt
-- leaves the record of what ran.
CREATE TABLE claude_runs (
    id              TEXT PRIMARY KEY,
    project_slug    TEXT NOT NULL,
    thread_slug     TEXT NOT NULL,
    prompt_id       TEXT NOT NULL,
    -- finished, failed or cancelled
    status          TEXT NOT NULL,
    model           TEXT NOT NULL DEFAULT '',
    permission_mode TEXT NOT NULL DEFAULT '',
    started_at      TEXT NOT NULL,
    finished_at     TEXT NOT NULL,
    seconds         INTEGER NOT NULL DEFAULT 0,
    turns           INTEGER,
    body            TEXT NOT NULL,
    FOREIGN KEY (project_slug, thread_slug) REFERENCES threads(project_slug, slug) ON DELETE CASCADE
);
CREATE INDEX claude_runs_by_prompt ON claude_runs (prompt_id, started_at);

-- The deliverables a run wrote or changed, by path relative to the project's deliverables/ folder.
CREATE TABLE claude_run_files (
    run_id   TEXT NOT NULL REFERENCES claude_runs(id) ON DELETE CASCADE,
    position INTEGER NOT NULL,
    path     TEXT NOT NULL,
    PRIMARY KEY (run_id, path)
);

-- The manifest of an uploaded file: when, where it is (relative to the project folder) and a description.
CREATE TABLE uploads (
    id           TEXT PRIMARY KEY,
    project_slug TEXT NOT NULL,
    thread_slug  TEXT NOT NULL,
    file         TEXT NOT NULL,
    name         TEXT NOT NULL,
    size         INTEGER NOT NULL DEFAULT 0,
    uploaded_at  TEXT NOT NULL,
    description  TEXT NOT NULL DEFAULT '',
    FOREIGN KEY (project_slug, thread_slug) REFERENCES threads(project_slug, slug) ON DELETE CASCADE
);

-- Every file under a project's deliverables/ folder, whatever its type. `body` is the text of a markdown file and
-- NULL for anything else, whose bytes stay on disk. A published version is its own row, named "<name>@v1.0.<ext>".
CREATE TABLE deliverables (
    project_slug TEXT NOT NULL REFERENCES projects(slug) ON DELETE CASCADE,
    path         TEXT NOT NULL,
    size         INTEGER NOT NULL DEFAULT 0,
    modified     TEXT NOT NULL,
    body         TEXT,
    PRIMARY KEY (project_slug, path)
);

-- How a published version came to be: who made the change, where it is filed, and the AI-use label (MMM) declared
-- for the product at that version. Kept as versions/<id>.md in the project. `thread_slug`, `prompt_id` and `run_id`
-- are deliberately not foreign keys: deleting a thread, a prompt or a note must not erase how a version came about.
-- `author` is 'ai', 'human', or '' when the origin was never recorded.
CREATE TABLE version_records (
    id               TEXT PRIMARY KEY,
    project_slug     TEXT NOT NULL REFERENCES projects(slug) ON DELETE CASCADE,
    deliverable_path TEXT NOT NULL,
    version          TEXT NOT NULL,
    thread_slug      TEXT,
    prompt_id        TEXT,
    run_id           TEXT,
    author           TEXT NOT NULL DEFAULT '',
    mmm              TEXT,
    sha256           TEXT,
    note             TEXT NOT NULL DEFAULT '',
    created_at       TEXT NOT NULL,
    UNIQUE (project_slug, deliverable_path, version)
);

-- scope '' is a vault-wide template, otherwise it is the slug of the project the template belongs to.
CREATE TABLE templates (
    scope      TEXT NOT NULL,
    id         TEXT NOT NULL,
    name       TEXT NOT NULL,
    "trigger"  TEXT NOT NULL DEFAULT '',
    body       TEXT NOT NULL DEFAULT '',
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL,
    PRIMARY KEY (scope, id)
);

CREATE TABLE template_questions (
    scope       TEXT NOT NULL,
    template_id TEXT NOT NULL,
    position    INTEGER NOT NULL,
    question    TEXT NOT NULL,
    PRIMARY KEY (scope, template_id, position),
    FOREIGN KEY (scope, template_id) REFERENCES templates(scope, id) ON DELETE CASCADE
);

-- The id is chosen by the user (e.g. MM01) and unique within the project, ignoring case.
CREATE TABLE user_stories (
    project_slug TEXT NOT NULL REFERENCES projects(slug) ON DELETE CASCADE,
    id           TEXT NOT NULL COLLATE NOCASE,
    summary      TEXT NOT NULL,
    role         TEXT NOT NULL DEFAULT '',
    want         TEXT NOT NULL DEFAULT '',
    reason       TEXT NOT NULL DEFAULT '',
    notes        TEXT NOT NULL DEFAULT '',
    created_at   TEXT NOT NULL,
    updated_at   TEXT NOT NULL,
    -- The Trello card this story is synced with, and, once that sync has stopped, why (see trello_sync.rs).
    trello_card     TEXT,
    trello_unlinked TEXT,
    PRIMARY KEY (project_slug, id)
);

CREATE TABLE acceptance_criteria (
    project_slug TEXT NOT NULL,
    story_id     TEXT NOT NULL COLLATE NOCASE,
    position     INTEGER NOT NULL,
    text         TEXT NOT NULL,
    done         INTEGER NOT NULL DEFAULT 0,
    PRIMARY KEY (project_slug, story_id, position),
    FOREIGN KEY (project_slug, story_id) REFERENCES user_stories(project_slug, id) ON DELETE CASCADE
);

-- Many-to-many: a thread can serve several stories and a story can span several threads.
CREATE TABLE story_threads (
    project_slug TEXT NOT NULL,
    story_id     TEXT NOT NULL COLLATE NOCASE,
    thread_slug  TEXT NOT NULL,
    PRIMARY KEY (project_slug, story_id, thread_slug),
    FOREIGN KEY (project_slug, story_id) REFERENCES user_stories(project_slug, id) ON DELETE CASCADE,
    FOREIGN KEY (project_slug, thread_slug) REFERENCES threads(project_slug, slug) ON DELETE CASCADE
);

-- A card on the project's board. `story_id` and `thread_slug` are optional links; they are cleared in code when
-- the story or thread goes away (a composite key can't be set to null without nulling the project too).
CREATE TABLE tasks (
    id           TEXT PRIMARY KEY,
    project_slug TEXT NOT NULL,
    title        TEXT NOT NULL,
    body         TEXT NOT NULL DEFAULT '',
    column_id    TEXT NOT NULL,
    story_id     TEXT COLLATE NOCASE,
    thread_slug  TEXT,
    created_at   TEXT NOT NULL,
    updated_at   TEXT NOT NULL,
    -- The Trello card this task is synced with, and, once that sync has stopped, why (see trello_sync.rs).
    trello_card     TEXT,
    trello_unlinked TEXT,
    FOREIGN KEY (project_slug, column_id) REFERENCES project_columns(project_slug, id),
    FOREIGN KEY (project_slug) REFERENCES projects(slug) ON DELETE CASCADE
);

-- A semester: half a year, set by hand, cut into sprints (three weeks unless chosen otherwise). Kept as
-- semesters/<id>.md. Dates are calendar days, "2026-09-01", inclusive at both ends.
CREATE TABLE semesters (
    id           TEXT PRIMARY KEY,
    name         TEXT NOT NULL,
    start_date   TEXT NOT NULL,
    end_date     TEXT NOT NULL,
    sprint_weeks INTEGER NOT NULL DEFAULT 3,
    notes        TEXT NOT NULL DEFAULT '',
    created_at   TEXT NOT NULL,
    updated_at   TEXT NOT NULL
);

CREATE TABLE sprints (
    semester_id TEXT NOT NULL REFERENCES semesters(id) ON DELETE CASCADE,
    position    INTEGER NOT NULL,
    name        TEXT NOT NULL,
    start_date  TEXT NOT NULL,
    end_date    TEXT NOT NULL,
    goal        TEXT NOT NULL DEFAULT '',
    PRIMARY KEY (semester_id, position)
);

-- Days off within a semester, in order and not overlapping. Sprints are counted in days of work, around them.
CREATE TABLE vacations (
    semester_id TEXT NOT NULL REFERENCES semesters(id) ON DELETE CASCADE,
    position    INTEGER NOT NULL,
    name        TEXT NOT NULL,
    start_date  TEXT NOT NULL,
    end_date    TEXT NOT NULL,
    PRIMARY KEY (semester_id, position)
);

-- ---- Portflow (see portflow.rs) ----------------------------------------------------------------------------------
-- Which Portflow collection a project is in, per semester (one collection per project per semester). Kept in
-- project.md as `portflowCollections`, whether or not Portflow is switched on.
CREATE TABLE project_collections (
    project_slug  TEXT NOT NULL REFERENCES projects(slug) ON DELETE CASCADE,
    semester_id   TEXT NOT NULL,
    collection_id INTEGER NOT NULL,
    PRIMARY KEY (project_slug, semester_id)
);

-- Everything below is only filled in while Portflow is switched on: its files are not read otherwise.

-- The learning outcomes, mirrored from Portflow (portflow/outcomes/<id>-<slug>.md). Never made or edited in Ledger.
CREATE TABLE outcomes (
    id            INTEGER PRIMARY KEY,
    name          TEXT NOT NULL,
    nickname      TEXT NOT NULL DEFAULT '',
    position      INTEGER NOT NULL DEFAULT 0,
    goal_set_id   INTEGER,
    goal_set      TEXT NOT NULL DEFAULT '',
    -- The template import it came with, shared with its section (see portflow_sections).
    import_id     INTEGER,
    status        TEXT NOT NULL DEFAULT '',
    -- Markdown, converted from Portflow's HTML.
    explanation   TEXT NOT NULL DEFAULT '',
    -- Gone from Portflow: kept so that links to it keep a name.
    removed       INTEGER NOT NULL DEFAULT 0,
    -- When it last changed here (not written to the file, so an unchanged sync writes nothing).
    synced_at     TEXT NOT NULL
);

CREATE TABLE sub_outcomes (
    id          INTEGER PRIMARY KEY,
    outcome_id  INTEGER NOT NULL REFERENCES outcomes(id) ON DELETE CASCADE,
    name        TEXT NOT NULL,
    nickname    TEXT NOT NULL DEFAULT '',
    position    INTEGER NOT NULL DEFAULT 0,
    description TEXT NOT NULL DEFAULT '',
    -- How many evidence items in the whole portfolio count for it, as Portflow counts them.
    evidence_count INTEGER NOT NULL DEFAULT 0
);

-- The people the portfolio is shared with (portflow/people.md): who can be tagged on feedback.
CREATE TABLE portflow_people (
    id         INTEGER PRIMARY KEY,
    name       TEXT NOT NULL,
    role       TEXT NOT NULL DEFAULT '',
    share_type TEXT NOT NULL DEFAULT '',
    expires    TEXT,
    position   INTEGER NOT NULL DEFAULT 0
);

-- A linked collection as Portflow last showed it (projects/<p>/portflow/<semester-id>.md).
CREATE TABLE collection_mirrors (
    project_slug  TEXT NOT NULL REFERENCES projects(slug) ON DELETE CASCADE,
    semester_id   TEXT NOT NULL,
    collection_id INTEGER NOT NULL,
    name          TEXT NOT NULL,
    subtitle      TEXT NOT NULL DEFAULT '',
    section       TEXT NOT NULL DEFAULT '',
    color         TEXT NOT NULL DEFAULT '',
    -- Markdown, converted from Portflow's HTML.
    description   TEXT NOT NULL DEFAULT '',
    synced_at     TEXT NOT NULL,
    PRIMARY KEY (project_slug, semester_id)
);

CREATE TABLE collection_outcomes (
    project_slug TEXT NOT NULL,
    semester_id  TEXT NOT NULL,
    outcome_id   INTEGER NOT NULL,
    position     INTEGER NOT NULL,
    PRIMARY KEY (project_slug, semester_id, outcome_id),
    FOREIGN KEY (project_slug, semester_id) REFERENCES collection_mirrors(project_slug, semester_id) ON DELETE CASCADE
);

-- An evidence item (projects/<p>/evidence/<slug>.md): what is handed in, as one or more files delivered and versioned
-- together. It belongs to at most one thread (where its feedback lands); a thread can hold several.
CREATE TABLE evidence (
    project_slug  TEXT NOT NULL REFERENCES projects(slug) ON DELETE CASCADE,
    slug          TEXT NOT NULL,
    name          TEXT NOT NULL,
    -- Deliberately not a foreign key: deleting a thread leaves the evidence item, unplaced.
    thread_slug   TEXT,
    portflow_id   INTEGER,
    -- file, free_text, url, video, lms_submission or badge.
    kind          TEXT NOT NULL DEFAULT 'file',
    description   TEXT NOT NULL DEFAULT '',
    created_at    TEXT NOT NULL,
    updated_at    TEXT NOT NULL,
    PRIMARY KEY (project_slug, slug)
);
CREATE UNIQUE INDEX evidence_by_portflow ON evidence (portflow_id) WHERE portflow_id IS NOT NULL;

-- The evidence item's files, by their path under deliverables/ (without a version). A file is in one item at most.
CREATE TABLE evidence_files (
    project_slug  TEXT NOT NULL,
    evidence_slug TEXT NOT NULL,
    position      INTEGER NOT NULL,
    path          TEXT NOT NULL,
    PRIMARY KEY (project_slug, path),
    FOREIGN KEY (project_slug, evidence_slug) REFERENCES evidence(project_slug, slug) ON DELETE CASCADE ON UPDATE CASCADE
);

-- The collections (per semester) the evidence item is shown in.
CREATE TABLE evidence_collections (
    project_slug  TEXT NOT NULL,
    evidence_slug TEXT NOT NULL,
    semester_id   TEXT NOT NULL,
    collection_id INTEGER NOT NULL,
    PRIMARY KEY (project_slug, evidence_slug, semester_id),
    FOREIGN KEY (project_slug, evidence_slug) REFERENCES evidence(project_slug, slug) ON DELETE CASCADE ON UPDATE CASCADE
);

-- The learning outcomes (goals and sub-goals, by their Portflow id) the evidence item counts for.
CREATE TABLE evidence_outcomes (
    project_slug  TEXT NOT NULL,
    evidence_slug TEXT NOT NULL,
    outcome_id    INTEGER NOT NULL,
    PRIMARY KEY (project_slug, evidence_slug, outcome_id),
    FOREIGN KEY (project_slug, evidence_slug) REFERENCES evidence(project_slug, slug) ON DELETE CASCADE ON UPDATE CASCADE
);

-- Portflow version N of an evidence item is major N of each of its files.
CREATE TABLE evidence_versions (
    project_slug     TEXT NOT NULL,
    evidence_slug    TEXT NOT NULL,
    number           INTEGER NOT NULL,
    portflow_version INTEGER,
    kind             TEXT NOT NULL DEFAULT 'file',
    -- Markdown: the changelog that went with it.
    description      TEXT NOT NULL DEFAULT '',
    created_at       TEXT NOT NULL,
    PRIMARY KEY (project_slug, evidence_slug, number),
    FOREIGN KEY (project_slug, evidence_slug) REFERENCES evidence(project_slug, slug) ON DELETE CASCADE ON UPDATE CASCADE
);

-- The files of each version, by Portflow's name. Ledger doesn't copy Portflow's files: a version that came from Ledger
-- points at the deliverable it is (a published "<name>@vN.0.<ext>", `path`); one uploaded in Portflow has no `path`
-- and is opened in Portflow.
CREATE TABLE evidence_version_files (
    project_slug  TEXT NOT NULL,
    evidence_slug TEXT NOT NULL,
    number        INTEGER NOT NULL,
    name          TEXT NOT NULL,
    portflow_file INTEGER,
    path          TEXT,
    PRIMARY KEY (project_slug, evidence_slug, number, name),
    FOREIGN KEY (project_slug, evidence_slug, number) REFERENCES evidence_versions(project_slug, evidence_slug, number) ON DELETE CASCADE ON UPDATE CASCADE
);
